    @EventHandler
    public void handle( CreateReinsuranceAgreementEvent event) {
        entityManager.persist(new ReinsuranceAgreement(event.getReinsuranceAgreementId(), event.getAgreementNumber(), event.getEffectivePeriod(), event.getRetention(), event.getLimit(), event.getCessionPercentage(), event.getInsurer(), event.getPolicies(), event.getReinsuranceType(), event.getTreatyType()));
    }

